import os
import torch


class Config:
    """
    Configuration for the High-Capacity Bottlenecked-Decoupled BiGRU (HC-BD-BiGRU) strategy.
    Centralizes file paths, model hyperparameters, and training settings.
    """

    # =========================================================================
    # Directories and File Paths
    # =========================================================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_64"

    # Metadata paths (Parquet files generated by metadata script)
    TRAIN_PATH = os.path.join(METADATA_DIR, "train.parquet")
    VAL_PATH = os.path.join(METADATA_DIR, "val.parquet")
    TEST_PATH = os.path.join(METADATA_DIR, "test.parquet")

    # Raw input paths
    SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")
    SUBMISSION_PATH = os.path.join(WORKING_DIR, "submission.csv")

    # Model Checkpoint
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # =========================================================================
    # Data Specifications
    # =========================================================================
    SEQ_LEN = 107
    SEQ_SCORED = 68

    # Input Features:
    # 4 Nucleotides (A, G, C, U) +
    # 3 Structure (., (, )) +
    # 7 Loop Types (S, M, I, B, H, E, X)
    INPUT_DIM = 14

    # Target Columns
    # All 5 provided in training data
    TARGET_COLS = ["reactivity", "deg_Mg_pH10", "deg_pH10", "deg_Mg_50C", "deg_50C"]
    NUM_TARGETS = len(TARGET_COLS)

    # Scored Columns (subset used for competition metric)
    SCORED_COLS = ["reactivity", "deg_Mg_pH10", "deg_Mg_50C"]

    # =========================================================================
    # Model Hyperparameters (HC-BD-BiGRU)
    # =========================================================================
    # Backbone: 4-Layer Bidirectional GRU
    # Hidden Dim: 384 per direction -> 768 total output
    HIDDEN_DIM = 384
    BIDIRECTIONAL = True
    NUM_LAYERS = 4

    # Stem (Convolutional)
    STEM_KERNEL_SIZE = 3
    STEM_FILTERS = 256

    # Bottlenecked Decoupled Interaction Module
    # Projects [h_i; h_j] (1536 dim) -> Bottleneck (96 dim) -> Gate
    BOTTLENECK_DIM = 96

    DROPOUT = 0.1

    # =========================================================================
    # Training Settings
    # =========================================================================
    SEED = 2024
    BATCH_SIZE = 32
    EPOCHS = 50
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4
    MAX_GRAD_NORM = 1.0  # Gradient clipping for stability

    # Early Stopping
    PATIENCE = 10

    # System
    NUM_WORKERS = 4
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    def __init__(self):
        """
        Initialize configuration and ensure necessary directories exist.
        """
        os.makedirs(self.WORKING_DIR, exist_ok=True)


# Instantiate config to trigger directory creation if imported
config = Config()
